use crate::tables::stop_word_tables::STOP_WORDS;
use crate::types::analysis_token::AnalysisToken;

/// The stop words of `lang` (a key of Dgraph's `langStops`), sorted bytewise.
pub(crate) fn stop_words(lang: &str) -> Option<&'static [&'static str]> {
    STOP_WORDS
        .binary_search_by_key(&lang, |&(l, _)| l)
        .ok()
        .map(|i| STOP_WORDS[i].1)
}

/// bleve's `StopTokensFilter.Filter`: the tokens whose term is not a stop word.
pub(crate) fn filter(words: &[&str], input: Vec<AnalysisToken>) -> Vec<AnalysisToken> {
    input
        .into_iter()
        .filter(|t| {
            words
                .binary_search_by(|w| w.as_bytes().cmp(t.term()))
                .is_err()
        })
        .collect()
}
